  "sided": 2,
  "power": 0.8,
  "effect_size": 0.13,
  "effect_type": "proportions",
  "control_rate": 0.07,
  "dropout": null,
  "analyses": [
    {
      "endpoint_ids": ["ep_1"],
      "method": "Clopper-Pearson CI",
      "quote": "Ninety-five percent Clopper-Pearson CIs for the ORR will be calculated."
    },
    {
      "endpoint_ids": ["ep_1"],
      "method": "exact test",
      "quote": "The primary efficacy analyses will be the comparison of the study BICR RECIST v1.1 confirmed ORR to a 7% ORR assumed under the null hypothesis (Hodi-2016) using a 2-sided exact test for the ITT Analysis Set."
    },
    {
      "endpoint_ids": ["ep_1", "ep_4", "ep_7", "ep_10"],
      "method": "summary",
      "quote": "The objective response rate per RECIST v1.1, iRECIST, and itRECIST by Investigator assessments will also be summarized."
    },
    {
      "endpoint_ids": ["ep_1"],
      "method": "summary",
      "quote": "The confirmed disease control rate is defined as the proportion of subjects in the analysis set who have a confirmed best response of CR, PR, or stable disease (SD)."
    },
    {
      "endpoint_ids": ["ep_4"],
      "method": "summary",
      "quote": "The treatment effect in non-injected target lesions will be assessed separately from the overall effect. The confirmed ORR in non-injected target lesions based the RECIST v1.1 BICR measurements will be summarized."
    },
    {
      "endpoint_ids": ["ep_3"],
      "method": "Kaplan-Meier",
      "quote": "Duration of response will be based on RECIST v1.1 as determined by BICR and calculated for responders."
    },
    {
      "endpoint_ids": ["ep_3", "ep_7"],
      "method": "Kaplan-Meier",
      "quote": "Duration of response and iDOR will also be determined by Investigator assessment per RECIST and iRECIST."
    },
    {
      "endpoint_ids": ["ep_5"],
      "method": "Kaplan-Meier",
      "quote": "Median PFS will be calculated using the Kaplan-Meier method."
    },
    {
      "endpoint_ids": ["ep_5", "ep_7"],
      "method": "Kaplan-Meier",
      "quote": "Analysis of PFS and iPFS based on RECIST v1.1 and iRECIST determined by Investigator assessment will also be performed."
    },
    {
      "endpoint_ids": ["ep_6"],
      "method": "Kaplan-Meier",
      "quote": "Median OS will be calculated using the Kaplan-Meier method."
    },
    {
      "endpoint_ids": ["ep_10"],
      "method": "summary",
      "quote": "Post-progression disease assessments of tumor response based on iRECIST by Investigator assessment will be summarized."
    },
    {
      "endpoint_ids": ["ep_10"],
      "method": "exploratory",
      "quote": "Exploratory efficacy analyses may also be performed to evaluate the effect of CMP-001 in combination with nivolumab on injected and noninjected target lesions."
    }
  ]
}
